class _Shelf extends StatelessWidget{const _Shelf({required this.icon,required this.title,required this.subtitle,this.accent=false});final IconData icon;final String title,subtitle;final bool accent;@override Widget build(BuildContext context)=>Container(margin:const EdgeInsets.only(bottom:12),decoration:BoxDecoration(color:accent?const Color(0xFF123B31):const Color(0xFF0D2A24),borderRadius:BorderRadius.circular(18),border:Border.all(color:accent?const Color(0xFFDDBB70).withValues(alpha:.65):const Color(0xFF235044))),child:ListTile(onTap:(){showModalBottomSheet<void>(context:context,showDragHandle:true,isScrollControlled:true,builder:(sheetContext)=>SafeArea(child:Padding(padding:const EdgeInsets.fromLTRB(24,12,24,28),child:Column(mainAxisSize:MainAxisSize.min,crossAxisAlignment:CrossAxisAlignment.start,children:[Text(title,style:Theme.of(context).textTheme.headlineSmall),const SizedBox(height:12),Text(subtitle),const SizedBox(height:18),const Text('Ky modul është në zhvillim. Funksioni nuk është ende aktiv; nuk janë ngarkuar apo ndryshuar skedarë.',style:TextStyle(color:Colors.grey)),const SizedBox(height:18),FilledButton(onPressed:()=>Navigator.pop(sheetContext),child:const Text('Mbyll'))]))));},contentPadding:const EdgeInsets.symmetric(horizontal:18,vertical:8),leading:Container(width:44,height:44,decoration:BoxDecoration(color:const Color(0xFFDDBB70).withValues(alpha:.10),borderRadius:BorderRadius.circular(13)),child:Icon(icon,color:const Color(0xFFDDBB70))),title:Text(title,style:const TextStyle(fontWeight:FontWeight.w700)),subtitle:Text(subtitle,style:const TextStyle(color:Color(0xFF9DB4AA))),trailing:const Icon(Icons.chevron_right,color:Color(0xFFDDBB70))));}
